import { test, expect } from '@playwright/test';

test.describe('HTTP Status Codes Verification', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://the-internet.herokuapp.com/status_codes');
  });

  test('Verify 200 status code page', async ({ page }) => {
    await page.getByText('200').click();
    await expect(page).toHaveURL(/.*\/status_codes\/200/);
    await expect(page.getByText('This page returned a 200 status code')).toBeVisible();
  });

  test('Verify 404 status code page', async ({ page }) => {
    await page.goBack();
    await page.getByText('404').click();
    await expect(page.getByText('This page returned a 404 status code')).toBeVisible();
  });
});
